import unittest
from pricing import Line, discount, shipping, tax, total


class Regression(unittest.TestCase):
    def test_small_order_pays_shipping(self):
        self.assertEqual(shipping(4999), 599)
        self.assertEqual(total([Line("pen", 1000, 2)]), 2000 + 165 + 599)

    def test_exact_tax_is_unchanged(self):
        self.assertEqual(tax(2000), 165)

    def test_rounds_down_below_half(self):
        # 8.25% of 1010 is 83.325, which is 83, not 84.
        self.assertEqual(tax(1010), 83)

    def test_discount_floors_to_whole_cents(self):
        self.assertEqual(discount(999, 10), 99)

